1	//! Manifest reading and MatrixReport assembly for `callisto matrix`.
2	//! Private helpers only -- the public entry point is
3	//! `crate::commands::matrix::matrix`.
4	
5	/// Per-triple CI scheduling attributes for the 18 triples
6	/// `crate::napi::triple_to_role` recognises today. This table is NEW code:
7	/// `triple_to_role`'s `ManifestRole::Platform` carries only platform/arch/abi
8	/// and has no concept of hostRunner/useCross, so this cannot be derived from
9	/// it. Returns `None` for any triple `triple_to_role` does not recognise --
10	/// callers must treat that as the AC-011 diagnostic path, never a silent
11	/// default.
12	pub(crate) fn triple_host_runner_use_cross(triple: &str) -> Option<(&'static str, bool)> {
13	    Some(match triple {
14	        "aarch64-apple-darwin" => ("macos-latest", false),
15	        "x86_64-apple-darwin" => ("macos-13", false),
16	        "x86_64-unknown-linux-gnu" => ("ubuntu-latest", false),
17	        "x86_64-unknown-linux-musl" => ("ubuntu-latest", true),
18	        "aarch64-unknown-linux-gnu" => ("ubuntu-latest", true),
19	        "aarch64-unknown-linux-musl" => ("ubuntu-latest", true),
20	        "x86_64-pc-windows-msvc" => ("windows-latest", false),
21	        "i686-pc-windows-msvc" => ("windows-latest", false),
22	        "aarch64-pc-windows-msvc" => ("windows-latest", false),
23	        "armv7-unknown-linux-gnueabihf" => ("ubuntu-latest", true),
24	        "x86_64-unknown-freebsd" => ("ubuntu-latest", true),
25	        "aarch64-linux-android" => ("ubuntu-latest", true),
26	        "armv7-linux-androideabi" => ("ubuntu-latest", true),
27	        "riscv64gc-unknown-linux-gnu" => ("ubuntu-latest", true),
28	        "powerpc64le-unknown-linux-gnu" => ("ubuntu-latest", true),
29	        "s390x-unknown-linux-gnu" => ("ubuntu-latest", true),
30	        "wasm32-wasip1" => ("ubuntu-latest", false),
31	        "wasm32-unknown-unknown" => ("ubuntu-latest", false),
32	        _ => return None,
33	    })
34	}
35	
36	/// AC-001: artifactName embeds the package's own (already workspace-unique)
37	/// name alongside platform/arch/abi -- napi-rs's own published-package and
38	/// recommended-CI-artifact convention (e.g. `@scope/addon-darwin-arm64`,
39	/// `@scope/addon-linux-x64-gnu`), not the raw Rust target triple -- so two
40	/// packages sharing a triple never collide once fed through
41	/// `unique_by(.artifactName)` in `.github/actions/callisto-action/action.yml`.
42	pub(crate) fn artifact_name_for_package_platform(
43	    package_name: &str,
44	    platform: &str,
45	    arch: &str,
46	    abi: Option<&str>,
47	) -> String {
48	    match abi {
49	        Some(abi) => format!("{package_name}-{platform}-{arch}-{abi}"),
50	        None => format!("{package_name}-{platform}-{arch}"),
51	    }
52	}
53	
54	use std::path::Path;
55	
56	use callisto_model::{ManifestError, ManifestFormat, ManifestRole, PlatformTarget};
57	
58	use crate::error::GraphError;
59	use crate::napi::triple_to_role;
60	
61	/// Result of reading the `napi.targets` field from a package.json. Distinct
62	/// from `Option<Vec<String>>` so AC-001b (present-but-empty vs absent) is a
63	/// type-level distinction, not a magic-empty-vec convention.
64	#[derive(Clone, Debug, PartialEq, Eq)]
65	pub(crate) enum NapiTargetsField {
66	    Absent,
67	    Present(Vec<String>),
68	}
69	
70	/// Reads and parses `pkg_json_path` as JSON, if it exists. `Ok(None)` when
71	/// the file is absent -- not every package has a `package.json`.
72	///
73	/// Callers needing more than one field out of the same `package.json` (e.g.
74	/// both `napi.targets` and `engines.node`, see `build_matrix_report`) must
75	/// call this once and pass the resulting `Value` to each field-extraction
76	/// function (`read_napi_targets`, `read_engines_node`) rather than letting
77	/// each one independently re-read and re-parse the file from disk.
78	pub(crate) fn parse_package_json(pkg_json_path: &Path) -> Result<Option<serde_json::Value>, GraphError> {
79	    if !pkg_json_path.exists() {
80	        return Ok(None);
81	    }
82	    let content = std::fs::read_to_string(pkg_json_path).map_err(|e| {
83	        GraphError::Manifest(ManifestError::Read {
84	            path: pkg_json_path.to_path_buf(),
85	            message: e.to_string(),
86	        })
87	    })?;
88	    let val: serde_json::Value = serde_json::from_str(&content).map_err(|e| {
89	        GraphError::Manifest(ManifestError::Parse {
90	            path: pkg_json_path.to_path_buf(),
91	            format: ManifestFormat::PackageJson,
92	            message: e.to_string(),
93	        })
94	    })?;
95	    Ok(Some(val))
96	}
